CREATE TABLE "ActivationTransitionRule" (
    "fromState" "ActivationState" NOT NULL,
    "toState" "ActivationState" NOT NULL,

    CONSTRAINT "ActivationTransitionRule_pkey" PRIMARY KEY ("fromState","toState")
);

