-- Prisma stores DateTime values as UTC in "timestamp without time zone".
-- Pin the database session timezone to UTC so database-side defaults and
-- triggers agree with it whatever the server's own timezone is.
DO $$
BEGIN
  EXECUTE format('ALTER DATABASE %I SET timezone TO %L', current_database(), 'UTC');
END;
$$;

-- The state guard. Runs for every INSERT and every UPDATE of "state" on
-- "Activation", from any client:
--   - an activation can only be created in 'submitted';
--   - a state change must be a row in "ActivationTransitionRule";
--   - every accepted change is written to "AuditEvent" with the actor, note
--     and time passed in by set_config (see src/lib/activations/transition.ts).
CREATE FUNCTION ledgerfield_activation_state_guard() RETURNS trigger AS $$
DECLARE
  actor text := NULLIF(current_setting('ledgerfield.actor_id', true), '');
  note text := NULLIF(current_setting('ledgerfield.note', true), '');
  at_text text := NULLIF(current_setting('ledgerfield.at', true), '');
  event_at timestamp(3) := COALESCE(at_text::timestamp(3), (now() AT TIME ZONE 'UTC'));
  previous "ActivationState" := NULL;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'submitted' THEN
      RAISE EXCEPTION 'ledgerfield: illegal activation transition (new) -> %', NEW.state
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    IF NEW.state IS NOT DISTINCT FROM OLD.state THEN
      RETURN NEW;
    END IF;
    previous := OLD.state;
    IF NOT EXISTS (
      SELECT 1 FROM "ActivationTransitionRule" r
      WHERE r."fromState" = OLD.state AND r."toState" = NEW.state
    ) THEN
      RAISE EXCEPTION 'ledgerfield: illegal activation transition % -> %', OLD.state, NEW.state
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  INSERT INTO "AuditEvent" (kind, "activationId", "fromState", "toState", "actorId", detail, at)
  VALUES ('transition', NEW.id, previous, NEW.state, actor, note, event_at);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "Activation_state_guard"
  BEFORE INSERT OR UPDATE OF state ON "Activation"
  FOR EACH ROW EXECUTE FUNCTION ledgerfield_activation_state_guard();

-- The rule table itself is reference data: it changes only by migration.
CREATE TRIGGER "ActivationTransitionRule_read_only"
  BEFORE INSERT OR UPDATE OR DELETE ON "ActivationTransitionRule"
  FOR EACH STATEMENT EXECUTE FUNCTION ledgerfield_reject_mutation();
